using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEngine.LowLevel;
public class Script{
 static PlayerLoopSystem previousLoop;static float previousCapture;static List<ParticleSystem> systems;static List<object> rows;static bool spawned,finished;static string output;sealed class MainGameplayHook{}
 public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");output="OUTPUT_FILE";var clean=PlayerLoop.GetCurrentPlayerLoop();for(int i=0;i<clean.subSystemList.Length;i++){var phase=clean.subSystemList[i];if(phase.subSystemList==null)continue;var list=new List<PlayerLoopSystem>(phase.subSystemList);list.RemoveAll(x=>x.type!=null&&x.type.Name=="MainGameplayHook");phase.subSystemList=list.ToArray();clean.subSystemList[i]=phase;}PlayerLoop.SetPlayerLoop(clean);previousLoop=PlayerLoop.GetCurrentPlayerLoop();previousCapture=Time.captureDeltaTime;Time.captureDeltaTime=1f/60;systems=new List<ParticleSystem>();rows=new List<object>();var loop=PlayerLoop.GetCurrentPlayerLoop();bool installed=false;for(int i=0;i<loop.subSystemList.Length;i++)if(loop.subSystemList[i].type==typeof(UnityEngine.PlayerLoop.PostLateUpdate)){var p=loop.subSystemList[i];var list=new List<PlayerLoopSystem>(p.subSystemList);list.Add(new PlayerLoopSystem{type=typeof(MainGameplayHook),updateDelegate=Tick});p.subSystemList=list.ToArray();loop.subSystemList[i]=p;installed=true;break;}if(!installed)throw new Exception("No PostLateUpdate");File.WriteAllText(output,"{\"pending\":true}");PlayerLoop.SetPlayerLoop(loop);return "Native automatic start rotation started";}
 static void Tick(){if(finished)return;try{
 if(!spawned){foreach(uint seed in new uint[]{42,513,2147483648,3758096383})foreach(var shapeEnabled in new[]{false,true})foreach(var size3D in new[]{false,true})foreach(var rotation3D in new[]{false,true}){
  var go=new GameObject("rotation-gameplay"){hideFlags=HideFlags.HideAndDontSave};var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.startLifetime=new ParticleSystem.MinMaxCurve(10,20);main.startSpeed=new ParticleSystem.MinMaxCurve(1,3);main.startSizeX=new ParticleSystem.MinMaxCurve(2,4);main.startSizeY=new ParticleSystem.MinMaxCurve(5,7);main.startSizeZ=new ParticleSystem.MinMaxCurve(8,10);main.startColor=new ParticleSystem.MinMaxGradient(new Color(1,0,0,1),new Color(1,1,0,1));main.startSize3D=size3D;main.startRotation3D=rotation3D;main.startRotationX=new ParticleSystem.MinMaxCurve(0,Mathf.PI*2);main.startRotationY=main.startRotationX;main.startRotationZ=main.startRotationX;main.cullingMode=ParticleSystemCullingMode.AlwaysSimulate;var em=ps.emission;em.enabled=true;em.rateOverTime=0;em.SetBursts(new[]{new ParticleSystem.Burst(0,17)});var sh=ps.shape;sh.enabled=shapeEnabled;ps.useAutoRandomSeed=false;ps.randomSeed=seed;ps.Play();systems.Add(ps);
 }spawned=true;return;}
 foreach(var ps in systems){var particles=new ParticleSystem.Particle[20];var count=ps.GetParticles(particles);var values=new List<object>();for(int i=0;i<count;i++){var p=particles[i];values.Add(new{seed=p.randomSeed,lifetime=p.startLifetime,speed=p.velocity.magnitude,size=new[]{p.startSize3D.x,p.startSize3D.y,p.startSize3D.z},green=p.startColor.g,rotation=new[]{p.rotation3D.x,p.rotation3D.y,p.rotation3D.z}});}rows.Add(new{seed=ps.randomSeed,shape=ps.shape.enabled,size3D=ps.main.startSize3D,rotation3D=ps.main.startRotation3D,time=ps.time,dt=Time.deltaTime,particles=values});}
 File.WriteAllText(output,System.Text.Json.JsonSerializer.Serialize(new{isPlaying=Application.isPlaying,unityVersion=Application.unityVersion,driver="automatic burst, PostLateUpdate, no Emit or Simulate",systemSeed=17,rows}));Cleanup();
 }catch(Exception e){File.WriteAllText(output,System.Text.Json.JsonSerializer.Serialize(new{error=e.ToString()}));Cleanup();}}
 static void Cleanup(){finished=true;PlayerLoop.SetPlayerLoop(previousLoop);Time.captureDeltaTime=previousCapture;foreach(var ps in systems)if(ps!=null)UnityEngine.Object.DestroyImmediate(ps.gameObject);}
}

